import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import Webcam from "react-webcam";

function JoinExam() {
  const [exams, setExams] = useState([]);
  const [selectedExam, setSelectedExam] = useState(null);
  const [verificationResult, setVerificationResult] = useState(null);
  const [verified, setVerified] = useState(false);
  const [loading, setLoading] = useState(false);
  const [running, setRunning] = useState(false);

  const webcamRef = useRef(null);
  const token = localStorage.getItem("token");

  // 📚 Lade alle verfügbaren Prüfungen beim Start
  useEffect(() => {
    axios
      .get("http://127.0.0.1:8000/api/students/exams/", {
        headers: { Authorization: `Token ${token}` },
      })
      .then((res) => setExams(res.data))
      .catch((err) => console.error("Fehler beim Laden der Prüfungen:", err));
  }, [token]);

  // 📷 Starte alle 2 s einen Frame-Upload an /live-verify/
  useEffect(() => {
    if (!running) return;
    const interval = setInterval(async () => {
      const imageSrc = webcamRef.current?.getScreenshot();
      if (!imageSrc) return;

      const blob = await (await fetch(imageSrc)).blob();
      const form = new FormData();
      form.append("frame", blob, "frame.jpg");

      try {
        const res = await axios.post(
          "http://127.0.0.1:8000/api/students/live-verify/",
          form,
          {
            headers: {
              Authorization: `Token ${token}`,
              "Content-Type": "multipart/form-data",
            },
          }
        );

        setVerificationResult(res.data);
        if (res.data.verified) {
          setVerified(true);
          setRunning(false);
          joinExam(selectedExam.id);
        }
      } catch (err) {
        console.error("Fehler bei Live-Verification:", err);
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [running, selectedExam, token]);

  // 🧑‍🎓 Prüfung beitreten
  const joinExam = async (examId) => {
    setLoading(true);
    try {
      const res = await axios.post(
        `http://127.0.0.1:8000/api/students/exams/${examId}/join/`,
        {},
        { headers: { Authorization: `Token ${token}` } }
      );
      alert(res.data.message || "Erfolgreich beigetreten!");
      setVerified(false);
      setSelectedExam(null);
    } catch (err) {
      console.error(err);
      alert("Fehler beim Beitritt zur Prüfung.");
    } finally {
      setLoading(false);
    }
  };

  // 📸 Rendering
  return (
    <div style={{ padding: "20px" }}>
      <h2>📋 Prüfungen</h2>
      <ul>
        {exams.map((exam) => (
          <li key={exam.id} style={{ marginBottom: 10 }}>
            {exam.title} – {exam.date}
            <button
              style={{ marginLeft: 10 }}
              onClick={() => {
                setSelectedExam(exam);
                setVerified(false);
                setVerificationResult(null);
                setRunning(false);
              }}
            >
              Beitreten
            </button>
          </li>
        ))}
      </ul>

      {selectedExam && (
        <div style={{ marginTop: 30 }}>
          <h3>🧾 Live-Identitätsprüfung für {selectedExam.title}</h3>
          <p>
            Bitte halte dein <strong>Gesicht</strong> in die obere Box und deinen{" "}
            <strong>Studentenausweis</strong> in die untere Box. Die
            Verifikation läuft automatisch.
          </p>

          {/* Kamera + Rahmen */}
          <div style={{ position: "relative", display: "inline-block" }}>
            <Webcam
              ref={webcamRef}
              audio={false}
              screenshotFormat="image/jpeg"
              width={480}
              height={360}
              videoConstraints={{ facingMode: "user" }}
            />
            {/* Gesichtsrahmen */}
            <div
              style={{
                position: "absolute",
                top: "10%",
                left: "5%",
                width: "90%",
                height: "45%",
                border: "2px dashed #0066ff",
                borderRadius: "8px",
              }}
            />
            {/* Ausweisrahmen */}
            <div
              style={{
                position: "absolute",
                bottom: "5%",
                left: "5%",
                width: "90%",
                height: "25%",
                border: "2px dashed #00cc66",
                borderRadius: "8px",
              }}
            />
          </div>

          {/* Steuerung */}
          <div style={{ marginTop: 20 }}>
            {!running ? (
              <button onClick={() => setRunning(true)}>Live-Überprüfung starten</button>
            ) : (
              <button onClick={() => setRunning(false)}>Überprüfung stoppen</button>
            )}
          </div>

          {/* Ergebnisanzeige */}
          {verificationResult && (
            <div
              style={{
                marginTop: 20,
                background: "#f9f9f9",
                padding: 10,
                borderRadius: 8,
                fontFamily: "monospace",
              }}
            >
              <p>
                <strong>Gesicht erkannt:</strong>{" "}
                {String(verificationResult.face_detected)}
              </p>
              <p>
                <strong>Ausweis erkannt:</strong>{" "}
                {String(verificationResult.id_face_detected)}
              </p>
              <p>
                <strong>Gesichter stimmen überein:</strong>{" "}
                {String(verificationResult.faces_verified)}
              </p>
              <p>
                <strong>Name-Match:</strong>{" "}
                {String(verificationResult?.db_compare?.name_match)}
              </p>
              <p>
                <strong>Matrikelnummer-Match:</strong>{" "}
                {String(verificationResult?.db_compare?.matriculation_match)}
              </p>
              <p>
                <strong>Gesamt-Verifiziert:</strong> {String(verificationResult.verified)}
              </p>
            </div>
          )}

          {verified && (
            <p style={{ color: "green", fontWeight: "bold", marginTop: 20 }}>
              ✅ Identität bestätigt – du wirst zur Prüfung hinzugefügt …
            </p>
          )}

          {loading && <p>⏳ Wird verarbeitet …</p>}
        </div>
      )}
    </div>
  );
}

export default JoinExam;
